        for c in range(W):
            counter[grid[r][c]] += 1

    # Background is most frequent
    background = counter.most_common(1)[0][0]

    # Find dominant non-background color
    non_bg_counts = {k: v for k, v in counter.items() if k != background}
    if not non_bg_counts:
        return [[background] * W for _ in range(H)]

    dominant = max(non_bg_counts, key=non_bg_counts.get)

    # Directions for 4-connected neighbors
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Result grid
