    # First pass: count how many dominant-color neighbors each cell has
    neighbor_count = [[0] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == dominant:
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        neighbor_count[nr][nc] += 1

    # Second pass: fill cells that can be part of a dominant region
    for r in range(H):
        for c in range(W):
            # If originally dominant, keep it
